"""Writes crates/core/src/codata_table.rs from SciPy's CODATA table (scipy.constants).

Run from the repository root: python3 book/generator/data/make_codata.py
"""
import json
import scipy
import scipy.constants._codata as cd

out = [
    "// Generated by book/generator/data/make_codata.py from SciPy %s (%s); do not edit." % (scipy.__version__, cd._current_codata),
    "// (name, value, unit, absolute uncertainty, obsolete)",
    "#[rustfmt::skip]",
    "pub(crate) const TABLE: &[(&str, f64, &str, f64, bool)] = &[",
]
for k, (v, u, e) in cd.physical_constants.items():
    obsolete = k not in cd._current_constants
    out.append("    (%s, %r, %s, %r, %s)," % (json.dumps(k, ensure_ascii=False), float(v), json.dumps(u, ensure_ascii=False), float(e), "true" if obsolete else "false"))
out.append("];")
open("crates/core/src/codata_table.rs", "w").write("\n".join(out) + "\n")
